package com.myassist.assistant.ui;
import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.myassist.assistant.MyAssistApp;import com.myassist.assistant.network.*;import org.json.JSONObject;
public class HomeActivity extends AppCompatActivity{TextView online,error;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_home);((TextView)findViewById(R.id.tvWelcome)).setText("Welcome, "+MyAssistApp.session().fullName());online=findViewById(R.id.tvOnline);error=findViewById(R.id.tvError);findViewById(R.id.btnOnline).setOnClickListener(v->setOnline(true));findViewById(R.id.btnOffline).setOnClickListener(v->setOnline(false));findViewById(R.id.btnJobs).setOnClickListener(v->startActivity(new Intent(this,JobsActivity.class)));findViewById(R.id.btnProfile).setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));}void setOnline(boolean value){String path=value?"api/v1/assistant/online":"api/v1/assistant/offline";ApiService.run(ApiService.post(path,new JSONObject()),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject x){runOnUiThread(()->online.setText(value?"ONLINE":"OFFLINE"));}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));}});}}